import { ChangeDetectionStrategy, Component, DestroyRef, ElementRef, inject, OnInit, ViewChild } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { CasecardComponent } from '../../../shared/components/casecard/casecard.component';
import { Router } from '@angular/router';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { SkeletonComponent } from '../../../shared/components/skeleton/skeleton.component';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { TicketsComponent } from '../../../shared/components/tickets/tickets.component';
import { Subject } from 'rxjs';
import { Title } from '@angular/platform-browser';
import { UsercreationComponent } from '../../../adminpanel/components/casebuilder/usercreation/usercreation.component';
import { MatDialog } from '@angular/material/dialog';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatMenuModule } from '@angular/material/menu';
import { LogoutService } from '../../../core/services/logout/logout.service';
import { AvatarComponent } from '../../../shared/components/avatar/avatar.component';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { LanguageService } from '../../../core/services/language/language.service';
import { UserDashboardFacade } from '../../services/user-dashboard/user-dashboard.facade';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { DASHBOARD_ACTIONS, ScrollState, USERDASHBOARD_CONFIG, SKELETON_ARRAYS, USER_DATA_CONFIG } from '../../utility/user-panel-constants';

@Component({
  selector: 'app-userdashboard',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [],
  imports: [CommonModule, ButtonComponent, CasecardComponent, IconComponent, SkeletonComponent,
    NgScrollbarModule, MatMenuModule, TicketsComponent, MatTooltipModule, UsercreationComponent, AvatarComponent, TranslateModule],
  templateUrl: './userdashboard.component.html',
  styleUrl: './userdashboard.component.scss'
})
export class UserdashboardComponent implements OnInit {
  // Facade Injection
  readonly facade = inject(UserDashboardFacade);

  // Constants
  readonly dashboardActions = DASHBOARD_ACTIONS;
  readonly scrollStateEnum = ScrollState;

  // Other Injections
  private readonly title = inject(Title);
  private readonly translate = inject(TranslateService);
  private readonly router = inject(Router);
  private readonly commonFunction = inject(CommonfunctionService);
  private readonly dialog = inject(MatDialog);
  private readonly logoutService = inject(LogoutService);
  private readonly languageService = inject(LanguageService);
  private readonly destroyRef = inject(DestroyRef);

  @ViewChild('parent') parent!: ElementRef;

  // Local UI State
  scrollState: string = 'S';
  selectedTicketCaseId: string = null;
  ticketChange$: Subject<number> = new Subject();

  get skeletonArray(): number[] {
    return this.facade.cases().length ? SKELETON_ARRAYS.LOADED_SKELETON : SKELETON_ARRAYS.DEFAULT_SKELETON;
  }

  get avatarSkeletonArray(): number[] {
    return SKELETON_ARRAYS.AVATAR_SKELETON;
  }

  get teamSkeletonArray(): number[] {
    return SKELETON_ARRAYS.TEAM_SKELETON;
  }

  constructor() {
    // Monitor ticket changes to update facade
    this.ticketChange$.pipe(takeUntilDestroyed()).subscribe(caseId => {
      // Logic to refresh tickets if needed, facade handles this mostly
    });
  }

  ngOnInit() {
    this.translate.get('DASHBOARD.TITLE').subscribe(title => {
      this.title.setTitle(title || USER_DATA_CONFIG.FALLBACK_DASHBOARD_TITLE);
    });
    this.facade.initDashboard();
  }

  // Facade Actions
  onReachEnd() {
    this.facade.loadMore();
  }

  // UI Helper functions
  goToAdmin(): void {
    this.router.navigate([USERDASHBOARD_CONFIG.ADMIN_DASHBOARD]);
  }

  onScroll(state: string): void {
    this.scrollState = state;
  }

  private scrollRafId: number = 0;

  onScroll2(state: string, event: Event): void {
    if (this.scrollRafId) return;
    this.scrollRafId = requestAnimationFrame(() => {
      this.scrollRafId = 0;
      // Width of card (320px) + gap (24px) = 344px.
      // Trigger when ~2 cards are remaining (approx 700px) to simulate "reaching 8th card" prefetch.
      const threshold = 700;
      const element = event.target as HTMLElement;
      const scrollLeft = element.scrollLeft;
      const scrollWidth = element.scrollWidth;
      const clientWidth = element.clientWidth;

      if (scrollWidth - scrollLeft <= clientWidth + threshold) {
        this.scrollState = ScrollState.END;
        this.onReachEnd();
      } else if (scrollLeft === 0) {
        this.scrollState = ScrollState.START;
      } else {
        this.scrollState = ScrollState.MIDDLE;
      }
    });
  }

  viewTicket(action: string, caseItem: any): void {
    if (action === DASHBOARD_ACTIONS.VIEW_TICKET) {
      if (this.selectedTicketCaseId === caseItem.nCaseid) {
        this.selectedTicketCaseId = null;
        return;
      }
      const shouldEmitChange = !!this.selectedTicketCaseId;
      this.selectedTicketCaseId = caseItem.nCaseid;
      setTimeout(() => {
        this.parent.nativeElement.scrollTo({ top: USERDASHBOARD_CONFIG.SCROLL_TO_POSITION, behavior: USERDASHBOARD_CONFIG.SCROLL_BEHAVIOR });
      }, USERDASHBOARD_CONFIG.SCROLL_TIMEOUT);
      if (shouldEmitChange) {
        this.ticketChange$.next(caseItem.nCaseid);
      }
    } else if (action === DASHBOARD_ACTIONS.REAL_TIME) {
      const url = this.router.serializeUrl(
        this.router.createUrlTree([USERDASHBOARD_CONFIG.REALTIME_FEED, btoa(JSON.stringify({ nSesid: caseItem.nSesid ? caseItem.nSesid : 0, nCaseid: caseItem.nCaseid }))])
      );
      globalThis.open(url, '_blank');
    }
  }

  onTicketResponse(count: number): void {
    // legacy used ticketList.find...
    // now we update facade
    if (this.selectedTicketCaseId) {
      this.facade.updateTicketCount(this.selectedTicketCaseId, count);
    }
  }

  gotoRealtime(): void {
    this.commonFunction.goto(USERDASHBOARD_CONFIG.REALTIME_FEED);
  }

  accountSetting(): void {
    const data = {
      nUserid: this.facade.userProfile()?.nUserid,
      ismyfiles: USER_DATA_CONFIG.IS_MY_FILES
    };

    const dialogRef = this.dialog.open(UsercreationComponent, {
      width: USERDASHBOARD_CONFIG.DIALOG_WIDTH,
      height: USERDASHBOARD_CONFIG.DIALOG_HEIGHT,
      maxHeight: USERDASHBOARD_CONFIG.DIALOG_MAX_HEIGHT,
      panelClass: ['addusermodal', 'rounded-10', 'overflow-hidden'],
      backdropClass: 'profilebackdrop',
      data: data,
      position: {
        top: USERDASHBOARD_CONFIG.DIALOG_POSITION_TOP,
        right: USERDASHBOARD_CONFIG.DIALOG_POSITION_RIGHT
      }
    });

    dialogRef.afterClosed().subscribe(() => {
      // Logic kept from legacy (debugger used there)
    });
  }

  async logOut(): Promise<void> {
    await this.logoutService.logout();
    this.commonFunction.goto(USERDASHBOARD_CONFIG.LOGIN_PAGE);
  }

  updateUser(): void {
    // facade signal auto updates if profile changes logic handled there
    // or we re-init
  }
  
  trackByIndex(index: number): number {
    return index;
  }

  trackByNcaseid(index: number, item: any): any {
    return item.nCaseid;
  }
}